\end{table}

\section{The bottom degree modulo two and the trichotomy}\label{sec:trichotomy}

\begin{theorem}[\texttt{bDeg\_even\_of\_mod4\_lt2}]
If $n\equiv 0$ or $1\pmod 4$, then $\bdeg$ is even for every $r_1,r_2$.
\end{theorem}
\begin{proof}[Proof sketch]
Both contributions are even, so each summand is even regardless of $r_1,r_2$.
\end{proof}

\begin{theorem}[\texttt{bDeg\_mod\_two\_of\_mod4\_eq2}]
If $n\equiv 2\pmod 4$, then $\bdeg \equiv r_1+r_2\pmod 2$.
\end{theorem}
\begin{proof}[Proof sketch]
Both contributions are odd, so modulo $2$ each summand reduces to its coefficient.
\end{proof}

\begin{theorem}[\texttt{bDeg\_mod\_two\_of\_mod4\_eq3}]
If $n\equiv 3\pmod 4$, then $\bdeg \equiv r_2\pmod 2$.
\end{theorem}
\begin{proof}[Proof sketch]
The floor contribution is even and the triangular contribution is odd, so
$\bdeg \equiv r_2$; the real count $r_1$ cancels.
\end{proof}

\begin{theorem}[Contragredient Sign Trichotomy, \texttt{contraSign\_*}]\label{thm:trich}
The contragredient sign $(-1)^{\bdeg}$ is
\[
  (-1)^{\bdeg} =
  \begin{cases}
    +1 & n \equiv 0,1 \pmod 4 \quad (\text{all } F),\\
    (-1)^{r_1+r_2} & n \equiv 2 \pmod 4,\\
    (-1)^{r_2} & n \equiv 3 \pmod 4.
  \end{cases}
\]
\end{theorem}
\begin{proof}[Proof sketch]
Immediate from the previous three theorems, since $(-1)^m$ depends only on
$m\bmod 2$.
\end{proof}

\section{Archimedean rigidity}\label{sec:rigidity}

\begin{theorem}[Archimedean invisibility,
\texttt{contraSign\_indep\_of\_real\_places\_mod4\_eq3}]
Fix $n\equiv 3\pmod 4$ and a complex-place count $r_2$. Then for any two real-place
counts $r_1, r_1'$, the contragredient sign equals $(-1)^{r_2}$ in both cases. In
particular every totally real field ($r_2=0$) gives sign $+1$ when $n\equiv 3\pmod 4$.
\end{theorem}
\begin{proof}[Proof sketch]
By the previous theorem $\bdeg \equiv r_2\pmod 2$ independently of $r_1$.
\end{proof}

This is a genuine archimedean rigidity, invisible from the abstract
$\varepsilon(\disc)^{\bdeg}$ statement.

\section{Structural corollaries}\label{sec:struct}

\begin{theorem}[\texttt{contraSign\_sq}]
For all $F$ and $n$, $\big((-1)^{\bdeg}\big)^2 = 1$.
\end{theorem}
\begin{proof}[Proof sketch]
$(-1)^{\bdeg}\in\{\pm1\}$. Conceptually: the contragredient is an involution, so
applying \eqref{eq:star} twice gives $p^b(\pi) = s^2 p^b(\pi)$ with $s=(-1)^{\bdeg}$;
since $p^b(\pi)\ne0$, $s^2=1$.
\end{proof}

\begin{theorem}[\texttt{no\_selfDual\_of\_odd}]
Let $\pi$ be a generic cohomological representation of $\GL(n)/F$ with
$p^b(\pi)\ne0$. If $\bdeg$ is odd, then $\pi$ is not self-dual.
\end{theorem}
\begin{proof}[Proof sketch]
Self-duality forces $s=+1$ in \eqref{eq:star}, while oddness forces $s=-1$; a
contradiction using only $p^b(\pi)\ne0$.
\end{proof}

Combining with Theorem~\ref{thm:trich}, no self-dual generic cohomological $\pi$
exists when $n\equiv 2\pmod 4$ with $r_1+r_2$ odd, or $n\equiv 3\pmod 4$ with $r_2$
odd --- a parity obstruction proved with no analytic input.

\section{Algorithms}
The classification is effective. Given $(n,r_1,r_2)$, the parity of $\bdeg$ is
computed in $O(1)$ from $n\bmod 4$ and $r_1,r_2\bmod 2$: it is $0$ if
$n\equiv 0,1$; $(r_1+r_2)\bmod 2$ if $n\equiv 2$; and $r_2\bmod 2$ if $n\equiv 3$.
The sign is $+1$ when this parity is $0$ and $-1$ otherwise, and self-duality is
permitted exactly when the sign is $+1$.

\section{Discussion}
An abstract character-theoretic statement of a sign can hide concrete structure
that only emerges upon computing parities. The two elementary parity laws convert
an infinite family of period signs into a finite table, expose the disappearance of
the real places when $n\equiv 3$, and turn the soft expectation of self-duality into
a hard congruence test. The square-root-of-unity property shows the sign is forced
by involutivity, not by a choice of normalization.

\section{Future directions}

\begin{conjecture}[mod-4 periodicity of the period twist]
For every $F$ and $n\ge2$, the contragredient twist of the bottom Betti--Whittaker
period depends on $n$ only through $n\bmod 4$, with the trichotomy of
Theorem~\ref{thm:trich}. The parity laws make this collapse a theorem, transportable
to any period normalization differing by a sign.
\end{conjecture}

\begin{conjecture}[invisibility of real places for $n\equiv 3$]
For $n\equiv 3\pmod 4$, two fields with the same $r_2$ but arbitrary $r_1$ give the
same sign; every totally real field gives $+1$. This predicts an archimedean
rigidity checkable for $\GL(3)$ over real vs.\ mixed fields.
\end{conjecture}

\begin{conjecture}[self-duality is a parity obstruction]
A generic cohomological $\pi$ with nonzero bottom period is self-dual only if
$\bdeg$ is even; for $n\equiv2$ with $r_1+r_2$ odd, or $n\equiv3$ with $r_2$ odd, no
such self-dual $\pi$ exists. The obstruction needs only $p\ne0$.
\end{conjecture}

\begin{conjecture}[the sign is intrinsically a square root of unity]
Any normalization with $p(\pi^\vee)=s\cdot p(\pi)$ respecting $(\pi^\vee)^\vee=\pi$
satisfies $s^2=1$; $s=(-1)^{\bdeg}$ is the unique consistent value compatible with
the bottom degree.
\end{conjecture}

